longest_increasing_path(Matrix) -> Grid = list_to_tuple([list_to_tuple(Row) || Row <- Matrix]), Rows = tuple_size(Grid), Columns = tuple_size(element(1, Grid)), Cache = ets:new(path_cache, [set, private]), Best = lists:max([path(Row, Column, Grid, Rows, Columns, Cache) || Row <- lists:seq(1, Rows), Column <- lists:seq(1, Columns)]), ets:delete(Cache), Best. path(Row, Column, Grid, Rows, Columns, Cache) -> case ets:lookup(Cache, {Row, Column}) of [{_, Best}] -> Best; [] -> Value = element(Column, element(Row, Grid)), Best = 1 + lists:max([0 | [path(R, C, Grid, Rows, Columns, Cache) || {R, C} <- [{Row-1, Column}, {Row+1, Column}, {Row, Column-1}, {Row, Column+1}], R >= 1, R =< Rows, C >= 1, C =< Columns, element(C, element(R, Grid)) > Value]]), ets:insert(Cache, {{Row, Column}, Best}), Best end.
